    /**
     * Usage the customer owes for on a dimension: only permitted usage beyond a
     * finite exhausted allowance. An unlimited or unexhausted allowance, or a
     * plan that forbids overage, charges nothing.
     */
    static chargeableQuantity({
        usageTotal,
        usageEntitlement,
        overageAllowed,
    }: {
        usageTotal: number;
        usageEntitlement?: number | 'inf';
        overageAllowed?: overageAllowedEnum | string;
